window.bookSummaryJSON = "<p>Tantor Audio presents two must-listen novellas from <i>New York Times</i> best-selling author Shayla Black. </p> <p><i>Wicked to Love</i>: Just when Brandon Ross gave up on the woman he'd always wanted, he found the one he needed - right under his nose. </p> <p><i>Devoted to Wicked</i>: A one-night stand...or something more? Karis isn't sure until a thief strands her in Mexico, leaving her in need of a passport photo - and a hero - giving Cage a second chance to win her love. </p> <p>Contains mature themes.</p>"; 
